import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';
const root=path.resolve('target/course-presentation/incremental-browser-builds/cases'),output=path.resolve('target/course-presentation/raw-wasm-storage'),sha=f=>crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex'),json=f=>JSON.parse(fs.readFileSync(f,'utf8'));
const[mode,input,expected,limit='2']=process.argv.slice(2);fs.mkdirSync(output,{recursive:true});
const owned=f=>{const a=path.resolve(f);assert(a.startsWith(root+path.sep));assert(!fs.lstatSync(a).isSymbolicLink());return a;};
if(mode==='census'||mode==='pilot-plan'){
 const p=json(input),rows=[];for(const entry of fs.readdirSync(root,{withFileTypes:true})){if(!entry.isDirectory())continue;const folder=path.join(root,entry.name),prepared=path.join(folder,'prepared.json'),built=path.join(folder,'built.json'),file=path.join(folder,'raw.wasm'),anchor=path.join(folder,'compiler-artifacts/wasm32-unknown-unknown/debug/viewer_journey.wasm');if(![prepared,built,file,anchor].every(f=>fs.existsSync(f)))continue;
  const q=json(prepared),b=json(built),r=p.items[q.id];if(!r?.sourceRecord||!r.image||!['CAPTURED_AWAITING_ROOT_VISUAL_REVIEW','PUBLISHED_ROOT_REVIEWED'].includes(r.status))continue;assert.equal(b.status,'BUILT_IMAGE_ONLY_SOURCE_BOUND');const record=typeof r.sourceRecord==='string'?r.sourceRecord:r.sourceRecord.path,pinned=typeof r.sourceRecord==='string'?r.sourceRecordSha256:r.sourceRecord.sha256;if(pinned)assert.equal(sha(record),pinned);assert.deepEqual(json(record).source,q.source);assert.equal(json(record).image.sha256,r.image.sha256);
  const a=fs.statSync(owned(file),{bigint:true}),s=fs.statSync(owned(anchor),{bigint:true});assert.equal(a.size,s.size);assert.equal(a.dev,s.dev);if(a.ino===s.ino)continue;
  rows.push({id:q.id,file,anchor,size:Number(a.size),build:{path:built,sha256:sha(built)},sourceRecord:{path:record,sha256:sha(record)},beforeInode:String(a.ino),anchorInode:String(s.ino)});
 }
 const selected=mode==='pilot-plan'?rows.filter(r=>['66bd-walk-json-records-within-a-depth-limit','71aj-exercise-complete-and-ranged-original-drawings'].includes(r.id)):rows;
 if(mode==='pilot-plan'){assert.equal(selected.length,2);for(const r of selected){r.sha256=sha(r.file);assert.equal(sha(r.anchor),r.sha256);}}
 const plan={status:mode==='pilot-plan'?'HASH_VERIFIED_TWO_PAIR_PILOT_NOT_APPLIED':'SIZE_ONLY_CENSUS_NOT_HASH_QUALIFIED_NOT_APPLIED',script:{path:path.resolve(process.argv[1]),sha256:sha(process.argv[1])},progress:{path:path.resolve(input),sha256:sha(input)},pairs:selected.length,nominalDuplicateBytes:selected.reduce((n,r)=>n+r.size,0),scope:'Only completed source-bound immutable raw.wasm and its OWN same-case retained compiler artifact. No active target/workbench/source/PNG/old proof changes. All paths and bytes must remain present.',rows:selected};
 const file=path.join(output,mode+'-'+Date.now()+'.json');fs.writeFileSync(file,JSON.stringify(plan,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({file,sha256:sha(file),pairs:plan.pairs,nominalDuplicateBytes:plan.nominalDuplicateBytes}));
}else if(mode==='apply'){
 assert.equal(sha(input),expected);const plan=json(input);assert.equal(plan.status,'HASH_VERIFIED_TWO_PAIR_PILOT_NOT_APPLIED');assert.equal(sha(plan.script.path),plan.script.sha256);assert(Number.isInteger(Number(limit))&&Number(limit)>0&&Number(limit)<=2);
 const receipt=path.join(output,'pilot-application-'+Date.now()+'.jsonl');let count=0;fs.writeFileSync(receipt,JSON.stringify({status:'PILOT_STARTED_BEFORE_MUTATION',plan:{path:path.resolve(input),sha256:expected},maximumPairs:Number(limit),script:plan.script})+'\n',{flag:'wx'});
 for(const row of plan.rows.slice(0,Number(limit))){const file=owned(row.file),anchor=owned(row.anchor);assert.equal(anchor,path.join(path.dirname(file),'compiler-artifacts/wasm32-unknown-unknown/debug/viewer_journey.wasm'));assert.equal(sha(row.build.path),row.build.sha256);assert.equal(sha(row.sourceRecord.path),row.sourceRecord.sha256);assert.equal(sha(file),row.sha256);assert.equal(sha(anchor),row.sha256);
  const before=fs.statSync(file,{bigint:true}),source=fs.statSync(anchor,{bigint:true});assert.equal(before.size,BigInt(row.size));assert.equal(before.dev,source.dev);assert(source.nlink<8n);const temporary=file+'.storage-link-'+process.pid;assert(!fs.existsSync(temporary));fs.linkSync(anchor,temporary);
  try{fs.renameSync(temporary,file);}catch(error){if(fs.existsSync(temporary))fs.unlinkSync(temporary);throw error;}
  const after=fs.statSync(file,{bigint:true}),anchorAfter=fs.statSync(anchor,{bigint:true});assert.equal(sha(file),row.sha256);assert.equal(sha(anchor),row.sha256);assert.equal(after.ino,anchorAfter.ino);assert.equal(after.dev,anchorAfter.dev);assert.equal(after.size,BigInt(row.size));
  fs.appendFileSync(receipt,JSON.stringify({...row,beforeInode:String(before.ino),afterInode:String(after.ino),anchorInode:String(anchorAfter.ino),linkCount:Number(after.nlink),pathAndBytesPreserved:true})+'\n');count++;
 }
 console.log(JSON.stringify({receipt,sha256:sha(receipt),applied:count}));
}else throw Error('census PROGRESS | pilot-plan PROGRESS | apply PLAN PLAN_SHA MAX2');

